local settings = {flightStyle="Fly", pianoFavorites={},pianoLocalFiles={},pianoSort="popular",chessEngine="stockfish",chessHumanize=false,chessDelayMin=1.2,chessDelayMax=3.2, favorites = {}, waypoints = {}, theme = "Amber", reducedMotion = false, key = "M", dockKey="K", searchKey="T", flyKey="F", noclipKey="Z", espKey="E", speedKey="V",flightTierKey="Q", freecamKey="L", freecamTeleportKey="N", notifications=true,autoOpen=true,alignment="Center",uiScale=100,sounds=true, blur=false, designVersion="2.3", provider="ScriptBlox", discovery="Beliebt", scriptFavorites={}, volume=35, values={}, friendHighlights=true, staffHighlights=true, adminAutoHop=false, lowEffects=false, fpsCap=60}
if type(readfile) == "function" then
    local ok, data = pcall(function() return Http:JSONDecode(readfile(CONFIG.SaveFile)) end)
    if ok and type(data) == "table" then
        if type(data.favorites) == "table" then
            for k, v in pairs(data.favorites) do
                if type(k) == "string" and v == true then settings.favorites[k] = true end
            end
        end
        if type(data.pianoLocalFiles)=="table" then
            for _,entry in ipairs(data.pianoLocalFiles)do
                if #settings.pianoLocalFiles<2000 and type(entry)=="table" and entry.source=="local" and type(entry.path)=="string" and #entry.path<=240 and type(entry.filename)=="string" and type(entry.title)=="string" and type(entry.id)=="string" then
                    table.insert(settings.pianoLocalFiles,{source="local",path=entry.path,filename=entry.filename,title=entry.title,artist="",id=entry.id})
                end
            end
        end
        if type(data.pianoFavorites)=="table" then
            local count=0
            for file,value in pairs(data.pianoFavorites) do
                if count<10000 and type(file)=="string" and #file<=250 and value==true then settings.pianoFavorites[file]=true;count+=1 end
            end
        end
        if data.chessEngine=="local"then settings.chessEngine="local"end
        if data.pianoSort=="title" or data.pianoSort=="newest" then settings.pianoSort=data.pianoSort end
        if data.theme == "Neutral" or data.theme == "Mint" or data.theme == "Amber" or data.theme == "Blue" then settings.theme = data.theme end
        if not ({Fly=true,Mysterious=true,["Villain Fly"]=true,Superman=true,["Halloween Fly"]=true})[data.flightStyle] then data.flightStyle="Fly" end
        if data.flightStyle=="Fly" or data.flightStyle=="Mysterious" or data.flightStyle=="Villain Fly" or data.flightStyle=="Superman" or data.flightStyle=="Halloween Fly" then settings.flightStyle=data.flightStyle end
        settings.blur=false
        if data.designVersion~="2.2" and data.designVersion~="2.3" then settings.theme="Amber" end
        settings.friendHighlights=data.friendHighlights~=false; settings.staffHighlights=data.staffHighlights~=false
        settings.chessHumanize=data.chessHumanize==true
        do
            local low,high=tonumber(data.chessDelayMin),tonumber(data.chessDelayMax)
            if low and high and low==low and high==high and low>=0 and high<=60 and low<=high then settings.chessDelayMin=low;settings.chessDelayMax=high end
        end
        settings.adminAutoHop=data.adminAutoHop==true
        settings.lowEffects=data.lowEffects==true
        if data.provider=="RoScripts" then settings.provider=data.provider end
        if data.discovery=="Neu" or data.discovery=="Favoriten" then settings.discovery=data.discovery end
        settings.volume=math.clamp(tonumber(data.volume) or 35,0,1000)
        local tier=tonumber(data.flightTier)
        if tier and tier==tier and tier>=1 and tier<=4 then settings.flightTier=math.floor(tier) end
        local custom=tonumber(data.flightCustomSpeed)
        if custom and custom==custom and custom>=1 and custom<=10000 then settings.flightCustomSpeed=custom end
        if type(data.values)=="table" then settings.values=data.values end
        if type(data.waypoints)=="table" then settings.waypoints=data.waypoints end
        if type(data.scriptFavorites)=="table" then
            local count=0
            for key,entry in pairs(data.scriptFavorites) do
                if count<60 and type(key)=="string" and type(entry)=="table" and type(entry.slug)=="string" and type(entry.title)=="string" and (entry.provider=="ScriptBlox" or entry.provider=="RoScripts") then settings.scriptFavorites[key]=entry; count=count+1 end
            end
        end
        settings.fpsCap=tonumber(data.fpsCap) or 60
        settings.sounds=data.sounds~=false
        settings.notifications=data.notifications~=false; settings.autoOpen=data.autoOpen~=false
        if data.alignment=="Left" or data.alignment=="Right" then settings.alignment=data.alignment end
        settings.uiScale=math.clamp(tonumber(data.uiScale) or 100,50,120)
        for _,field in ipairs({"dockKey","searchKey","flyKey","noclipKey","espKey","speedKey","flightTierKey","freecamKey","freecamTeleportKey"}) do
            if type(data[field])=="string" then
                local valid,key=pcall(function() return Enum.KeyCode[data[field]] end)
                if valid and key and key~=Enum.KeyCode.Unknown then settings[field]=data[field] end
            end
        end
        settings.reducedMotion = data.reducedMotion==true
        if type(data.key) == "string" then
            local valid, key = pcall(function() return Enum.KeyCode[data.key] end)
            if valid and key and key ~= Enum.KeyCode.Unknown then settings.key = data.key end
        end
    end
end
if settings.key=="RightShift" then settings.key="M" end
local themes = {Neutral=Color3.fromRGB(92,108,127), Blue = Color3.fromRGB(77,151,255), Mint = Color3.fromRGB(85,216,165), Amber = Color3.fromRGB(225,112,39)}
C.accent = themes[settings.theme]
CONFIG.ToggleKey = Enum.KeyCode[settings.key]
if settings.dockKey==settings.key then settings.dockKey=settings.key=="K" and "J" or "K" end
if settings.searchKey==settings.key or settings.searchKey==settings.dockKey then
    for _,candidate in ipairs({"T","F","G","H"}) do
        if candidate~=settings.key and candidate~=settings.dockKey then settings.searchKey=candidate; break end
    end
end
local alive, connections, actions = true, {}, {}
do
    local used={}
    for _,field in ipairs({"key","dockKey","searchKey","flyKey","noclipKey","espKey","speedKey","flightTierKey","freecamKey","freecamTeleportKey"}) do
        if used[settings[field]] then
            for _,key in ipairs({"F","Z","E","V","K","T","M","G","H","B","N","J","L","U","Y","I","O","P","C","X","R"}) do
                if not used[key] then settings[field]=key; break end
            end
        end
        used[settings[field]]=true
    end
end
