local function decodeBase64(data)
    local result={}
    for i=1,#data,4 do
        local a,b,c,d=data:sub(i,i),data:sub(i+1,i+1),data:sub(i+2,i+2),data:sub(i+3,i+3)
        local value=(base64Values[a] or 0)*262144+(base64Values[b] or 0)*4096+(base64Values[c] or 0)*64+(base64Values[d] or 0)
        table.insert(result,string.char(math.floor(value/65536)%256))
        if c~="=" and c~="" then table.insert(result,string.char(math.floor(value/256)%256)) end
        if d~="=" and d~="" then table.insert(result,string.char(value%256)) end
    end
    return table.concat(result)
end
local function iconAsset(name)
    if iconCache[name]~=nil then return iconCache[name] or nil end
    iconCache[name]=false
    if not capabilities.icons or not ICON_DATA[name] then return nil end
    local ok,asset=pcall(function()
        local path="ISBMenu-icon-v2-"..name..".png"
        if type(isfile)~="function" or not isfile(path) then writefile(path,decodeBase64(ICON_DATA[name])) end
        local loader=type(getcustomasset)=="function" and getcustomasset or getsynasset
        return loader(path)
    end)
    if ok and type(asset)=="string" and asset~="" then iconCache[name]=asset; return asset end
end
local function imageIcon(parent,name,size,pos,color)
    local asset=iconAsset(name)
