end
playUISound=function(name,pitch)
    if not alive or not settings.sounds then return end
    local now=os.clock()
    local category=name=="hover" and "hover" or ((name=="notice" or name=="join" or name=="leave") and "notice" or name)
    if now-(runtime.soundTimes[category] or -100)<(category=="hover" and .085 or (category=="intro" and .08 or .12)) then return end
    runtime.soundTimes[category]=now
    local clip=runtime.prepareUISound(name); if not clip then return end
    clip.Volume=name=="intro" and .45 or .8; clip.PlaybackSpeed=pitch or 1
    pcall(function() clip:Stop(); clip:Play() end)
end

