local function drawIcon(parent,kind)
    local icon=imageIcon(parent,navAssetNames[kind],20,UDim2.fromOffset(8,8),C.muted)
    if icon then icon.Name="NavigationGlyph"; icon.Position=UDim2.fromScale(.5,.5); return {{obj=icon,property="ImageColor3"}} end
    kind=({1,2,3,7,4,6,5,6,7})[kind] or 7
    local holder=make("Frame",{BackgroundTransparency=1,Position=UDim2.fromOffset(8,8),Size=UDim2.fromOffset(20,20)},parent)
    local parts={}
    local function line(x1,y1,x2,y2)
        local dx,dy=x2-x1,y2-y1
        local part=make("Frame",{BorderSizePixel=0,BackgroundColor3=C.muted,AnchorPoint=Vector2.new(.5,.5),
            Position=UDim2.fromOffset((x1+x2)/2,(y1+y2)/2),Size=UDim2.fromOffset(math.sqrt(dx*dx+dy*dy),1.5),
            Rotation=math.deg(math.atan2(dy,dx))},holder)
        round(part,1); table.insert(parts,{obj=part,property="BackgroundColor3"})
    end
    local function circle(x,y,size)
        local f=make("Frame",{BackgroundTransparency=1,Position=UDim2.fromOffset(x,y),Size=UDim2.fromOffset(size,size)},holder)
        round(f,size/2)
        local s=make("UIStroke",{Color=C.muted,Thickness=1.5},f)
        table.insert(parts,{obj=s,property="Color"})
    end
    if kind==1 then
        line(2,9,10,2); line(10,2,18,9); line(3,8,3,18); line(17,8,17,18)
        line(3,18,8,18); line(12,18,17,18); line(8,18,8,12); line(12,18,12,12); line(8,12,12,12)
    elseif kind==2 then
        line(10,2,4,8); line(10,2,16,8); line(10,3,10,18); line(6,18,14,18)
    elseif kind==3 then
        circle(6,1,8); line(3,18,3,14); line(3,14,7,11); line(7,11,13,11); line(13,11,17,14); line(17,14,17,18)
    elseif kind==4 then
        line(10,1,19,10); line(19,10,10,19); line(10,19,1,10); line(1,10,10,1); circle(6,6,8)
    elseif kind==5 then
        line(7,15,7,4); line(7,4,17,2); line(17,2,17,13); circle(2,13,5); circle(12,11,5)
    elseif kind==6 then
        local points={}
        for n=0,9 do
            local a=math.rad(-90+n*36); local radius=n%2==0 and 9 or 4
            points[n+1]={10+math.cos(a)*radius,10+math.sin(a)*radius}
        end
        for n=1,10 do local a,b=points[n],points[n%10+1]; line(a[1],a[2],b[1],b[2]) end
    else
        circle(4,4,12); circle(8,8,4)
        for n=0,7 do local a=math.rad(n*45); line(10+math.cos(a)*6,10+math.sin(a)*6,10+math.cos(a)*9,10+math.sin(a)*9) end
    end
    return parts
end
