runtime.inventoryCache={}; runtime.inventoryDirty=true
function runtime.rebuildInventoryCache()
    table.clear(runtime.inventoryCache)
    for _,source in ipairs(runtime.inventoryRoots) do
        local record={source=source,screens={},containers={}}
        local ok,objects=pcall(function() return source:GetDescendants() end)
        record.readable=ok
        if ok then for _,obj in ipairs(objects) do
            if source==playerGui and obj:IsA("ScreenGui") and obj~=gui then table.insert(record.screens,obj) end
            if obj:IsA("GuiObject") then
                local own,named=false,false; local ancestor=obj
                while ancestor and ancestor~=source do
                    if ancestor==gui then own=true; break end
                    local name=ancestor.Name:lower()
                    if name:find("hotbar",1,true) or name:find("backpack",1,true) or name:find("inventory",1,true) or name:find("quickbar",1,true) or name:find("toolbelt",1,true) then named=true end
                    ancestor=ancestor.Parent
                end
                if named then
                    if not own then
                        local slots={}; for _,slot in ipairs(obj:GetDescendants()) do
                            if slot:IsA("ImageLabel") or slot:IsA("ImageButton") or slot:IsA("TextLabel") or slot:IsA("TextButton") then table.insert(slots,slot) end
                        end
                        table.insert(record.containers,{object=obj,slots=slots})
                    end
                end
            end
        end end
        table.insert(runtime.inventoryCache,record)
    end
    runtime.inventoryDirty=false
end
function runtime.inventoryChanged(obj)
    if not obj then runtime.inventoryDirty=true; return end
    local relevant=obj:IsA("ScreenGui"); local ancestor=obj
    while ancestor do
        if ancestor==gui or ancestor==runtime.voiceMicGui then return end
        local name=ancestor.Name:lower()
        if name:find("hotbar",1,true) or name:find("backpack",1,true) or name:find("inventory",1,true) or name:find("quickbar",1,true) or name:find("toolbelt",1,true) then relevant=true end
        ancestor=ancestor.Parent
    end
    if relevant then runtime.inventoryDirty=true end
end
for _,source in ipairs(runtime.inventoryRoots) do
    connect(source.DescendantAdded,runtime.inventoryChanged)
    if source.DescendantRemoving then connect(source.DescendantRemoving,runtime.inventoryChanged) end
    connect(source.ChildAdded,runtime.inventoryChanged)
end
function runtime.nativeInventoryClearance(viewport,center,half)
    -- Readable hotbars use their visible slots, never the number of stored Tools.
    for _,record in ipairs(runtime.inventoryCache) do
        if record.source~=playerGui and record.readable then return 18 end
    end
    local enabled=true
    local ok,value=pcall(function() return game:GetService("StarterGui"):GetCoreGuiEnabled(Enum.CoreGuiType.Backpack) end)
    if ok then enabled=value~=false end
    if not enabled then return 18 end
    local count=0
    local function countTools(parent)
        if parent then for _,item in ipairs(parent:GetChildren()) do if item:IsA("Tool") then count+=1 end end end
    end
    -- If CoreGui is inaccessible, only an equipped Tool justifies a fallback.
    countTools(player.Character)
    if count==0 then return 18 end
    local width=math.min(viewport.X,math.min(count,10)*70)
    local left=(viewport.X-width)*.5
    if left+width<center-half or left>center+half then return 18 end
    return 96
end
function runtime.updateInventoryClearance()
    local camera=workspace.CurrentCamera
    if not camera then return end
    local viewport=camera.ViewportSize
    local clearance,order=18,90
    local half=300*scale.Scale
    local center=settings.alignment=="Left" and 12+half or (settings.alignment=="Right" and viewport.X-12-half or viewport.X*.5)
    if runtime.inventoryDirty then runtime.rebuildInventoryCache() end
    clearance=math.max(clearance,runtime.nativeInventoryClearance(viewport,center,half))
    for _,record in ipairs(runtime.inventoryCache) do
        local source=record.source
        for _,screen in ipairs(record.screens) do
            if screen.Parent and screen~=runtime.voiceMicGui and screen.Enabled~=false then order=math.max(order,math.min(2147483646,(screen.DisplayOrder or 0)+1)) end
        end
        do
            for _,candidate in ipairs(record.containers) do
                local obj=candidate.object
                if obj.Parent then
                    local valid,top=pcall(function()
                        local visible,named=true,false
                        local ancestor=obj
                        while ancestor and ancestor~=source do
                            if ancestor==gui then return nil end
                            if ancestor:IsA("GuiObject") and (not ancestor.Visible or (ancestor:IsA("CanvasGroup") and ancestor.GroupTransparency>=.99)) then visible=false; break end
                            if ancestor:IsA("ScreenGui") and not ancestor.Enabled then visible=false; break end
                            local name=ancestor.Name:lower()
                            if name:find("hotbar",1,true) or name:find("backpack",1,true) or name:find("inventory",1,true) or name:find("quickbar",1,true) or name:find("toolbelt",1,true) then named=true end
                            ancestor=ancestor.Parent
                        end
                        if not visible or not named then return nil end
                        local absolute,size=obj.AbsolutePosition,obj.AbsoluteSize
                        local origin=gui.AbsolutePosition
                        local position=Vector2.new(absolute.X-origin.X,absolute.Y-origin.Y)
                        local ownName=obj.Name:lower()
                        local inventoryPanel=(ownName:find("inventory",1,true) or ownName:find("backpack",1,true))
                            and size.X>=120 and size.Y>=120 and size.Y<=viewport.Y*.9
                        if inventoryPanel then
                            if position.Y<0 or position.Y>=viewport.Y or position.X+size.X<center-half or position.X>center+half then return nil end
                            -- An open backpack blocks the dock even when all its slots are empty.
                            return position.Y-12
                        end
                        -- A native hotbar with only the inspector Tool is a single narrow slot.
                        if size.X<32 or size.Y<20 or size.Y>math.min(220,viewport.Y*.3) then return nil end
                        if position.Y<viewport.Y*.65 or position.Y>=viewport.Y or position.Y+size.Y<=0 then return nil end
                        if position.X+size.X<center-half or position.X>center+half then return nil end
                        local occupied=false
                        for _,slot in ipairs(candidate.slots) do
                            if slot.Parent and slot.Visible then
                                local shown=true; local parent=slot.Parent
                                while parent and parent~=obj do
                                    if parent:IsA("GuiObject") and not parent.Visible then shown=false; break end
                                    parent=parent.Parent
                                end
                                if source~=playerGui then
                                    local slotName=slot.Name:lower()
                                    shown=shown and (slotName=="toolicon" or slotName=="toolname" or slotName=="icon" or slotName=="itemicon" or slotName=="itemname")
                                end
                                if shown and ((slot:IsA("ImageLabel") or slot:IsA("ImageButton")) and slot.Image~=""
                                    or (slot:IsA("TextLabel") or slot:IsA("TextButton")) and slot.Text~="" and not tostring(slot.Text):match("^%d+$")) then occupied=true; break end
                            end
                        end
                        if not occupied then return nil end
                        return position.Y
                    end)
                    if valid and top then clearance=math.max(clearance,viewport.Y-top+12) end
                end
            end
        end
    end
    gui.DisplayOrder=order
    if runtime.voiceMicGui then runtime.voiceMicGui.DisplayOrder=math.max(1000,order+1) end
    if runtime.dockClearance~=clearance then runtime.dockClearance=clearance; fit() end
end
