                if type(Marketplace.GetProductInfoAsync)=="function" then return Marketplace:GetProductInfoAsync(tonumber(id),Enum.InfoType.Asset) end
                return Marketplace:GetProductInfo(tonumber(id),Enum.InfoType.Asset)
            end)
