function runtime.drawRuler(parent,action)
    local function formatValue(value)
        return string.format("%.2f",value):gsub("0+$",""):gsub("%.$","")
    end
    local valueBox=make("TextBox",{Name="NumericValue_"..action.id,Text=formatValue(action.get()),ClearTextOnFocus=false,
        Font=Enum.Font.BuilderSansMedium,TextSize=16,TextColor3=C.text,BackgroundColor3=Color3.fromRGB(32,39,47),
        Position=UDim2.new(1,-141,0,10),Size=UDim2.fromOffset(92,32)},parent)
    round(valueBox,10)
    local viewport=make("Frame",{Name="RollingRuler",Active=true,BackgroundTransparency=1,ClipsDescendants=true,
        Position=UDim2.fromOffset(16,57),Size=UDim2.new(1,-32,0,45)},parent)
    round(viewport,12)
    local needle=make("Frame",{Name="RulerNeedle",BackgroundColor3=C.accent,AnchorPoint=Vector2.new(.5,0),
        Position=UDim2.fromScale(.5,0),Size=UDim2.fromOffset(2,23),ZIndex=3},viewport)
    round(needle,1)
    local marks={}
    for i=0,math.floor((action.max-action.min)/action.step) do
        local value=action.min+action.step*i
        local major=action.id=="flyspeed" or value%(action.id=="fovvalue" and 5 or 10)==0
        local tick=make("Frame",{Name="RulerTick",BackgroundColor3=C.muted,BackgroundTransparency=major and .2 or .62,
            Size=UDim2.fromOffset(1,major and 18 or 10),AnchorPoint=Vector2.new(.5,0)},viewport)
        local caption
        if action.id=="flyspeed" or value%(action.id=="fovvalue" and 10 or 20)==0 or value==action.min or value==action.max then caption=label(viewport,string.format("%g",math.floor(value*10+.5)/10),9,C.muted,UDim2.new(),UDim2.fromOffset(50,14));caption.TextXAlignment=Enum.TextXAlignment.Center end
        table.insert(marks,{value=value,tick=tick,caption=caption})
    end
    local hint=label(parent,"",9,C.muted,UDim2.fromOffset(16,105),UDim2.new(1,-32,0,15))
    local function paint(value,soft)
        valueBox.Text=formatValue(action.id=="flyspeed" and runtime.flightLevel().speed or value)
        local selected=math.clamp(value,action.min,action.max)
        for _,mark in ipairs(marks) do
            local x=action.id=="flyspeed" and (.5+(mark.value-selected)*48/math.max(viewport.AbsoluteSize.X,1)) or (.5+(mark.value-selected)/(action.max-action.min))
            local edgeDistance=math.min(x,1-x)
            local opacity=math.clamp(edgeDistance/.12,0,1)
            local base=mark.tick.Size.Y.Offset==18 and .2 or .62
            mark.tick.BackgroundTransparency=1-(1-base)*opacity
            if mark.caption then mark.caption.TextTransparency=1-opacity end
            local position=UDim2.new(x,0,0,4)
            if soft then animate(mark.tick,{Position=position}) else mark.tick.Position=position end
            if mark.caption then
                local position=UDim2.new(x,-25,0,27)
                if soft then animate(mark.caption,{Position=position}) else mark.caption.Position=position end
            end
        end
        hint.Text=(value~=selected and "Manueller Wert \194\183 " or "Skala ziehen \194\183 ")..action.min.."\226\128\147"..action.max.." \194\183 Zahl antippen zum Eingeben"
        if action.id=="flyspeed" then hint.Text="Skala: Stufe 1-4 \194\183 Zahl: Geschwindigkeit in studs/s" end
    end
    local function apply(value,dragging)
        if dragging and action.preview then action.preview(value) else action.fn(value); save() end
        paint(action.get())
    end
    paint(action.get())
    runtime.actionRefresh=runtime.actionRefresh or {}
    runtime.actionRefresh[action.id]=function() if parent.Parent then paint(action.get(),true) end end
    rowConnect(viewport.InputBegan,function(input)
        if input.UserInputType~=Enum.UserInputType.MouseButton1 and input.UserInputType~=Enum.UserInputType.Touch then return end
        content.ScrollingEnabled=false
        local startX=input.Position.X
        local startValue=math.clamp(action.get(),action.min,action.max)
        activeSlider={id=action.id,input=input,finish=action.commit,update=function(x)
            local value=action.id=="flyspeed" and (startValue-(x-startX)/48) or (startValue-(x-startX)/math.max(viewport.AbsoluteSize.X,1)*(action.max-action.min))
            local step=action.dragStep or action.step
            value=math.clamp(math.floor(value/step+.5)*step,action.min,action.max)
            apply(value,true)
        end}
    end)
    rowConnect(valueBox.FocusLost,function()
        local value=tonumber((valueBox.Text:gsub(",",".")))
        local maximum=action.id=="flyspeed" and 10000 or action.id=="uiscale" and 120 or (action.id=="mediavolume" and 100 or (action.id=="volume" and 1000 or (action.id=="fovvalue" and 120 or 10000)))
        local minimum=action.id=="flyspeed" and 1 or action.id=="uiscale" and 50 or (action.id=="fovvalue" and 1 or 0)
        if not value or value~=value or value<minimum or value>maximum then
            paint(action.get()); notify("Bitte eine Zahl zwischen "..minimum.." und "..maximum.." eingeben.",action.name); return
        end
        if action.id=="flyspeed" then runtime.setFlightSpeed(math.floor(value*100+.5)/100); save(); paint(action.get())
        else apply(math.floor(value*100+.5)/100) end
    end)
end
