                if nextCommand.seekPending and runtime.media.seekPending==nextCommand.seekPending then runtime.media.seekPending=nil; runtime.mediaProgress() end
                if nextCommand.playbackPending and runtime.media.playbackPending==nextCommand.playbackPending then
                    runtime.media.state.playing=nextCommand.playbackPending.original; runtime.media.playbackPending=nil; runtime.mediaPaint()
                end
                notify(ok and tostring(result.error or "Aktion nicht angenommen.") or tostring(result):sub(1,150),"Musik") end
        end
        runtime.media.commanding=false; runtime.media.pollTime=0; if alive then runtime.mediaPoll() end
    end)
end
function runtime.previewMediaVolume(value)
    if not runtime.media.state.controls or not runtime.media.state.controls.volume then return end
    runtime.media.state.volume=value/100
    runtime.media.volumePending={value=value/100,untilTime=os.clock()+2}
end
function runtime.commitMediaVolume()
    local pending=runtime.media.volumePending
    if pending and pending.value~=runtime.media.lastVolumeSent then
        pending.untilTime=os.clock()+2; runtime.media.lastVolumeSent=pending.value; runtime.mediaCommand("volume",pending.value)
    end
end
