function features.detectGameStaff(other,joined)
    task.spawn(function()
        local detected=table.find(CONFIG.StaffUserIds,other.UserId)~=nil
        local roleLabel=detected and "Staff" or "Player"
        pcall(function()
            if game.CreatorType==Enum.CreatorType.User then detected=detected or other.UserId==game.CreatorId; if other.UserId==game.CreatorId then roleLabel="Owner" end; return end
            if game.CreatorType~=Enum.CreatorType.Group then return end
            local groupService=game:GetService("GroupService")
            local ok,result=pcall(function() return groupService:GetRolesInGroupAsync(other.UserId,game.CreatorId) end)
            local roles=ok and type(result)=="table" and result.Roles or nil
            if not roles then
                local fallback,role=pcall(function() return other:GetRoleInGroupAsync(game.CreatorId) end)
                roles=fallback and {{Name=role}} or {}
            end
            table.sort(roles,function(a,b) return (a.Rank or 0)>(b.Rank or 0) end)
            if roles[1] and type(roles[1].Name)=="string" then roleLabel=roles[1].Name end
            for _,role in ipairs(roles) do
                local name=tostring(role.Name or ""):gsub("(%l)(%u)","%1 %2"):lower():gsub("[^%w]"," ")
                local padded=" "..name.." "
                if not padded:find(" not ",1,true) and not padded:find(" fan ",1,true) and not padded:find(" former ",1,true) and not padded:find(" ex ",1,true) then
                    for _,term in ipairs({"admin","administrator","owner","coowner","co owner","developer","dev","moderator","mod","staff","manager","management","helper","support","supporter","support staff","support team","besitzer","mitbesitzer","entwickler","leitung","helfer"}) do
                        if padded:find(" "..term.." ",1,true) then detected=true; break end
                    end
                end
                if role.Rank==255 then detected=true end
            end
        end)
        if not alive or not other.Parent then return end
        local previous=runtime.gameStaff[other]
        local previousRole=runtime.groupRoles[other]
        runtime.gameStaff[other]=detected
        runtime.groupRoles[other]=roleLabel
        if detected and other~=player then runtime.adminHop.tick()end
        if page=="Spieler" and (previous~=detected or previousRole~=roleLabel) and refreshPlayers then refreshPlayers() end
        if detected and not previous and other~=player then notify(other.DisplayName..(joined and " ist dem Server beigetreten." or " geh\195\182rt zur Spiel-Leitung."),joined and "Admin beigetreten" or "Spiel-Admin","shield-check") end
    end)
end
