    if not target then
        local aliases={RightHand="Right Arm",["Right Arm"]="RightHand",LeftHand="Left Arm",["Left Arm"]="LeftHand"}
        target=aliases[part.Name] and visible:FindFirstChild(aliases[part.Name])
    end
    if not target then return nil end
    local copy=target:FindFirstChild(attachment.Name,true)
    if not copy or not copy:IsA("Attachment") then
        copy=Instance.new("Attachment");copy.Name="ISBToolEffectAttachment"
        local position=localFrame.Position
        copy.CFrame=CFrame.new(position.X*target.Size.X/part.Size.X,position.Y*target.Size.Y/part.Size.Y,position.Z*target.Size.Z/part.Size.Z)*localFrame.Rotation
        copy.Parent=target;table.insert(visual.effectAttachments,copy)
    end
    visual.objects[attachment]=copy
    return copy
end
function runtime.outfitToolEffects(body,visual,firstPerson)
    for source,copy in pairs(visual.objects) do
        if source:IsA("Attachment") and source.Parent and copy.Parent then
            local ancestor=source.Parent;local internal=false
            while ancestor do if ancestor==visual.tool then internal=true;break end;ancestor=ancestor.Parent end
            if internal then
                copy.CFrame=source.CFrame
                if source:IsA("Bone") then copy.Transform=source.Transform end
            end
        end
    end
    for _,entry in ipairs(visual.effects) do
        local source,copy=entry.source,entry.copy
        if source.Parent and copy.Parent then
            local current=source[entry.property]
            if current~=entry.mask then entry.original=current end
            copy[entry.property]=firstPerson and entry.mask or entry.original
            copy.Enabled=source.Enabled and not firstPerson and entry.valid~=false
            source[entry.property]=entry.mask
            if source:IsA("Beam") or source:IsA("Trail") then
                for _,property in ipairs({"Attachment0","Attachment1"}) do
                    local attachment=source[property]
                    copy[property]=runtime.outfitToolEffectAttachment(body,visual,attachment)
                end
                copy.Enabled=copy.Enabled and copy.Attachment0~=nil and copy.Attachment1~=nil
            end
        elseif copy.Parent then copy.Enabled=false end
    end
end
function runtime.prepareOutfitToolEffects(visual)
    for source,copy in pairs(visual.objects) do
        local property,mask
        if source:IsA("ParticleEmitter") or source:IsA("Trail") or source:IsA("Beam") then property="LocalTransparencyModifier";mask=1
        elseif source:IsA("PointLight") or source:IsA("SpotLight") or source:IsA("SurfaceLight") then property="Brightness";mask=0 end
        if property and copy.Parent then
            local entry={source=source,copy=copy,property=property,mask=mask,original=source[property]}
            table.insert(visual.effects,entry)
            if source.Changed then
                table.insert(visual.effectConnections,source.Changed:Connect(function(changed)
                    if changed==property then
                        if source[property]~=mask then entry.original=source[property] end
                    elseif changed~="Parent" and changed~="Attachment0" and changed~="Attachment1" then
                        pcall(function() copy[changed]=source[changed] end)
                    end
                end))
            end
            copy.Enabled=false
            if copy:IsA("ParticleEmitter") or copy:IsA("Trail") then copy:Clear() end
        end
    end
end

function runtime.updateOutfitTools(body,firstPerson)
    if body.toolsDirty then table.clear(body.toolFailures) end
    for tool in pairs(body.toolFailures) do if tool.Parent~=body.character then body.toolFailures[tool]=nil end end
    for tool,visual in pairs(body.toolVisuals) do
        if tool.Parent~=body.character or not visual.handle.Parent or body.toolsDirty then runtime.clearOutfitTool(body,tool) end
    end
    body.toolsDirty=false
    for _,tool in ipairs(body.character:GetChildren()) do
        local handle=tool:IsA("Tool") and tool:FindFirstChild("Handle")
        if handle and handle:IsA("BasePart") and not body.toolFailures[tool] then
            local visual=body.toolVisuals[tool]
            if not visual then
                local model=Instance.new("Model"); model.Name="ISBOutfitToolVisual"
                visual={model=model,tool=tool,handle=handle,parts={},hidden={},objects={},effects={},effectAttachments={},effectConnections={}}
                body.toolVisuals[tool]=visual
                local ok=pcall(function()
                    for _,part in ipairs(tool:GetDescendants()) do if part:IsA("BasePart") then
                        local flags={[part]=part.Archivable}
                        for _,item in ipairs(part:GetDescendants()) do flags[item]=item.Archivable end
                        for item in pairs(flags) do item.Archivable=true end
                        local cloned,copy=pcall(function() return part:Clone() end)
                        for item,value in pairs(flags) do item.Archivable=value end
                        if not cloned or not copy then error("Tool appearance unavailable") end
                        local clonedObjects={}
                        for _,item in ipairs(copy:GetDescendants()) do clonedObjects[runtime.outfitRigPath(item,copy)]=item end
                        visual.objects[part]=copy
                        for _,item in ipairs(part:GetDescendants()) do
                            local ancestor=item.Parent;local nested=false
                            while ancestor and ancestor~=part do if ancestor:IsA("BasePart") then nested=true;break end;ancestor=ancestor.Parent end
                            if not nested and not item:IsA("BasePart") then visual.objects[item]=clonedObjects[runtime.outfitRigPath(item,part)] end
                        end
                        -- Clone visuals only; gameplay stays on the untouched original Tool.
                        for _,item in ipairs(copy:GetDescendants()) do
                            if item:IsA("LuaSourceContainer") or item:IsA("BasePart") or item:IsA("JointInstance") or item:IsA("WeldConstraint") or item:IsA("Constraint") or item:IsA("BodyMover") or item:IsA("Sound") or item:IsA("ProximityPrompt") or item:IsA("ClickDetector") then item:Destroy() end
                        end
                        copy.Anchored=true;copy.CanCollide=false;copy.CanTouch=false;copy.CanQuery=false;copy.Massless=true
                        copy.Parent=model
                        table.insert(visual.parts,{source=part,part=copy})
                        visual.hidden[part]=part.LocalTransparencyModifier
                    end end
                end)
                if ok and #visual.parts>0 then runtime.prepareOutfitToolEffects(visual);model.Parent=workspace else runtime.clearOutfitTool(body,tool);body.toolFailures[tool]=true;visual=nil end
            end
            if visual then
                local frame=runtime.outfitToolMount(body,visual)
                if frame then
                frame=runtime.outfitOverheadFrame(body,visual,frame)
                for _,entry in ipairs(visual.parts) do if entry.source.Parent then
                    entry.part.CFrame=frame and frame*handle.CFrame:ToObjectSpace(entry.source.CFrame) or entry.source.CFrame
                    entry.part.Transparency=entry.source.Transparency
                    entry.part.LocalTransparencyModifier=firstPerson and 1 or visual.hidden[entry.source]
                    entry.source.LocalTransparencyModifier=1
                end end
                runtime.outfitToolEffects(body,visual,firstPerson)
                else runtime.clearOutfitTool(body,tool);body.toolFailures[tool]=true end
            end
        end
    end
end

function runtime.stopOutfitBody()
    local body=runtime.outfitBody
    if not body then return end
    runtime.outfitBody=nil
    Run:UnbindFromRenderStep("ISBOutfitBody")
    Run:UnbindFromRenderStep("ISBOutfitCameraPrepare")
    Run:UnbindFromRenderStep("ISBOutfitCamera")
    runtime.releaseOutfitCamera(body)
    for tool in pairs(body.toolVisuals) do runtime.clearOutfitTool(body,tool) end
    for _,connection in ipairs(body.connections) do connection:Disconnect() end
    for _,cached in pairs(body.animationTracks) do
        if cached then pcall(function() cached.track:Stop(0); cached.track:Destroy() end); cached.animation:Destroy() end
    end
    for part,value in pairs(body.hidden) do
        if part.Parent and part.LocalTransparencyModifier==1 then part.LocalTransparencyModifier=value end
    end
    if body.animationModel then body.animationModel:Destroy() end
    body.model:Destroy()
end
function runtime.updateOutfitBody()
    local body=runtime.outfitBody
    if not body then return end
    if not alive or player.Character~=body.character or not body.root.Parent or not body.model.Parent or not body.bodyRoot.Parent or (body.animationModel and not body.animationModel.Parent) or body.humanoid.Health<=0 then runtime.clearOutfit(false); return end
    local frame=body.root.CFrame*CFrame.new(0,body.lift,0)
    if body.animationRoot then
        if body.nativeClothing then body.animationModel:PivotTo(frame*body.animationRoot.PivotOffset)
        else body.animationRoot.CFrame=frame end
    end
    for _,entry in ipairs(body.parts) do entry.part.CFrame=frame*entry.offset end
    if body.animated then
        for bone,transform in pairs(body.bonePose) do if bone.Parent then bone.Transform=transform end end
    else
        for _,bone in ipairs(body.allBones) do bone.Transform=CFrame.new() end
        if body.actionPose then for _,bone in ipairs(body.bones) do if bone.source.Parent then bone.target.Transform=bone.source.Transform end end end
    end
    local holding=runtime.outfitHoldingArms(body)
    for _,edge in ipairs(body.ordered) do
        local joint=edge.joint
        local transform=CFrame.new()
        if joint.animated then
            if body.animated then transform=body.pose[joint.rig] or (joint.driver and joint.driver.Transform) or CFrame.new(); joint.rig.Transform=transform
            else transform=body.actionPose and joint.motor and joint.motor.Parent and joint.motor.Transform or CFrame.new(); joint.rig.Transform=transform end
        end
        if holding and joint.animated and runtime.outfitIsHoldingJoint(joint) then
            transform=runtime.outfitHeldArmPose(joint) or CFrame.new(); joint.rig.Transform=transform
        end
        local c0,c1=joint.c0,joint.c1
        if joint.attachment0 then
            local _,current0=runtime.outfitAttachmentFrame(joint.attachment0,true)
            local _,current1=runtime.outfitAttachmentFrame(joint.attachment1,true)
            c0,c1=current0,current1
        end
        if edge.reverse then edge.child.CFrame=edge.parent.CFrame*c1*transform:Inverse()*c0:Inverse()
        else edge.child.CFrame=edge.parent.CFrame*c0*transform*c1:Inverse() end
    end
    runtime.updateOutfitAccessories(body)
    for part in pairs(body.hidden) do if part.Parent then part.LocalTransparencyModifier=1 end end
    local camera=workspace.CurrentCamera
    local firstPerson=camera and camera.CameraSubject==body.humanoid and camera.CameraType~=Enum.CameraType.Scriptable and (camera.CFrame.Position-camera.Focus.Position).Magnitude<1
    for _,entry in ipairs(body.parts) do
        entry.part.LocalTransparencyModifier=(firstPerson or body.nativeClothing) and 1 or entry.transparency
        if body.nativeClothing and entry.driver then
            entry.driver.LocalTransparencyModifier=firstPerson and 1 or entry.transparency
            if not entry.connected then entry.driver.CFrame=entry.part.CFrame end
        end
    end
    runtime.updateOutfitTools(body,firstPerson)
end
function runtime.installOutfitBody(body)
    runtime.stopOutfitBody()
    runtime.outfitBody=body; body.model.Parent=workspace
    runtime.createOutfitAnimationRig(body)
    table.insert(body.connections,(Run.PreAnimation or Run.Heartbeat):Connect(function()
        if runtime.outfitBody==body then runtime.releaseOutfitToolArms(body);runtime.updateOutfitAnimation(body) end
    end))
    table.insert(body.connections,Run.PreSimulation:Connect(function()
        if runtime.outfitBody~=body then return end
        local holding=runtime.outfitHoldingArms(body)
        if not holding then runtime.releaseOutfitToolArms(body) end
        if not body.animated then
            for _,edge in ipairs(body.ordered) do
                local joint=edge.joint
                if joint.animated and joint.driver then
                    joint.driver.Transform=body.actionPose and joint.motor and joint.motor.Parent and joint.motor.Transform or CFrame.new()
                end
            end
            for _,bone in ipairs(body.animationBones) do bone.driver.Transform=CFrame.new() end
            if body.actionPose then
                for _,bone in ipairs(body.bones) do
                    for _,pair in ipairs(body.animationBones) do if pair.target==bone.target and bone.source.Parent then pair.driver.Transform=bone.source.Transform end end
                end
            end
        end
        for _,edge in ipairs(body.ordered) do
            local joint=edge.joint
            if joint.animated and joint.driver then
                if holding and runtime.outfitIsHoldingJoint(joint) then
                    local pose=runtime.outfitHeldArmPose(joint) or CFrame.new()
                    local owned=body.toolArmOverrides[joint.driver] or {before=joint.driver.Transform}
                    owned.applied=pose;body.toolArmOverrides[joint.driver]=owned; joint.driver.Transform=pose
                end
                if body.animated then body.pose[joint.rig]=joint.driver.Transform end
            end
        end
        if body.animated then for _,bone in ipairs(body.animationBones) do body.bonePose[bone.target]=bone.driver.Transform end end
    end))
    runtime.updateOutfitAnimation(body)
    for _,item in ipairs(body.character:GetDescendants()) do runtime.hideOutfitPart(body,item) end
    table.insert(body.connections,body.character.DescendantAdded:Connect(function(item) runtime.hideOutfitPart(body,item);body.toolsDirty=true end))
    runtime.updateOutfitBody()
    if runtime.outfitBody~=body then error("Character changed") end
    Run:BindToRenderStep("ISBOutfitCameraPrepare",Enum.RenderPriority.First.Value-1,function()
        if runtime.outfitBody==body then runtime.releaseOutfitCamera(body) end
    end)
    Run:BindToRenderStep("ISBOutfitCamera",Enum.RenderPriority.Last.Value+3,function()
        if runtime.outfitBody==body then runtime.updateOutfitCamera() end
    end)
    runtime.updateOutfitCamera()
    Run:BindToRenderStep("ISBOutfitBody",Enum.RenderPriority.Last.Value+2,function()
        local ok=pcall(runtime.updateOutfitBody)
        if not ok then
            runtime.clearOutfit(false)
            notify("Outfit-Kopie beendet. Bitte erneut versuchen.","Outfit Stealer")
        end
    end)
end
function runtime.copyOutfit(other,restore)
    if runtime.outfitBusy then notify("Outfit wird gerade geladen.","Outfit Stealer"); return end
    local char=player.Character; local h=humanoid()
    if not char or not h or h.Health<=0 then notify("Charakter ist gerade nicht verf\195\188gbar.","Outfit Stealer"); return end
    if restore then
        if not runtime.outfitBody then notify("Dein eigenes Outfit ist bereits aktiv.","Outfit Stealer"); return end
        runtime.clearOutfit(true); notify("Eigenes Outfit wiederhergestellt.","Outfit Stealer"); return
    end
    if not other or other==player or not other.Parent or not other.Character or not other.Character:FindFirstChildOfClass("Humanoid") then
        notify("Spieler ist gerade nicht verf\195\188gbar.","Outfit Stealer"); return
    end
    runtime.outfitBusy=true
    local generation=runtime.outfitGeneration; local source=other.Character
    task.spawn(function()
        local ok,body=pcall(runtime.prepareOutfitBody,source,char,h)
        local current=alive and generation==runtime.outfitGeneration and player.Character==char and other.Parent and other.Character==source
        if ok and not current then body.model:Destroy()
        elseif current then
            if ok then
                local installed=pcall(runtime.installOutfitBody,body)
                if installed then notify("K\195\182rper und Outfit lokal \195\188bernommen.","Outfit Stealer")
                else runtime.stopOutfitBody(); body.model:Destroy(); notify("Outfit konnte nicht angewendet werden. Bitte erneut versuchen.","Outfit Stealer") end
            else notify("K\195\182rper des Spielers konnte nicht vollst\195\164ndig kopiert werden. Bitte erneut versuchen.","Outfit Stealer") end
        end
        runtime.outfitBusy=false
    end)
end
function runtime.clearOutfit()
    runtime.outfitGeneration+=1
    runtime.stopOutfitBody()
end

