function runtime.finishExtraJump()
    local jump=runtime.extraJump; runtime.extraJump=nil
    if not jump or not state.infiniteJump or state.fly or runtime.roleplay or humanoid()~=jump.h or root()~=jump.root or jump.h.Health<=0 or jump.h.PlatformStand or jump.h.Sit then return end
    local velocity=jump.root.AssemblyLinearVelocity or Vector3.zero
    jump.root.AssemblyLinearVelocity=Vector3.new(velocity.X,jump.power,velocity.Z)
end
function runtime.requestExtraJump()
    local h=humanoid()
    local r=root()
    if state.infiniteJump and not state.fly and not runtime.roleplay and not UIS:GetFocusedTextBox() and h and r and h.Health>0 and not h.PlatformStand and not h.Sit then
        if os.clock()-(runtime.lastExtraJump or -1)<.12 then return end
        runtime.lastExtraJump=os.clock()
        if h:GetState()==Enum.HumanoidStateType.Jumping then h:ChangeState(Enum.HumanoidStateType.Freefall) end
        h.Jump=true
        h:ChangeState(Enum.HumanoidStateType.Jumping)
        local power=h.UseJumpPower and h.JumpPower or math.sqrt(2*math.max(workspace.Gravity,1)*h.JumpHeight)
        runtime.extraJump={h=h,root=r,power=power}
        local velocity=r.AssemblyLinearVelocity or Vector3.zero
        r.AssemblyLinearVelocity=Vector3.new(velocity.X,power,velocity.Z)
    end
end
connect(UIS.JumpRequest,runtime.requestExtraJump)
connect(UIS.InputBegan,function(input)
    if input.KeyCode==Enum.KeyCode.Space or input.KeyCode==Enum.KeyCode.ButtonA then runtime.requestExtraJump() end
end)
function runtime.keyName(code)
    local name=code.Name
    if #name==1 and name:match("%u") then
        local ok,text=pcall(function() return UIS:GetStringForKeyCode(code) end)
        if ok and type(text)=="string" and #text==1 and text:upper():match("%u") then return text:upper() end
        if name=="Y" then return "Z" elseif name=="Z" then return "Y" end
    end
    return name
end
connect(UIS.InputBegan,function(input,processed)
    if runtime.pianoSending then return end
    if runtime.piano and (runtime.piano.state=="playing" or runtime.piano.state=="paused" or runtime.piano.preview) and input.KeyCode==Enum.KeyCode.F8 then
        runtime.piano.stop();runtime.musicMode="piano";query="";page="Musik";setOpen(true);render();return
    end
    if runtime.piano and runtime.piano.state=="playing" then return end
    local pressed=runtime.keyName(input.KeyCode)
    if captureKey and input.UserInputType==Enum.UserInputType.Keyboard then
        local field=captureKey==true and "key" or captureKey
        captureKey=false
        if input.KeyCode~=Enum.KeyCode.Escape and input.KeyCode~=Enum.KeyCode.Unknown then
            for _,other in ipairs({"key","dockKey","searchKey","flyKey","noclipKey","espKey","speedKey","flightTierKey","freecamKey","freecamTeleportKey"}) do
                if other~=field and settings[other]==pressed then notify("Diese Taste wird bereits verwendet.","Tastenk\195\188rzel"); render(); return end
            end
            settings[field]=pressed
            if field=="key" then CONFIG.ToggleKey=input.KeyCode end
            save()
        end
        render(); return
    end
    if input.KeyCode==Enum.KeyCode.Escape and quickSearchOpen then setQuickSearch(false); return end
    if input.KeyCode==Enum.KeyCode.Escape and runtime.inspectorPanel and runtime.inspectorPanel.Visible then runtime.hideInspector(); return end
    if input.KeyCode==Enum.KeyCode.Escape and runtime.quickPanel and runtime.quickPanel.Visible then runtime.quickPanel.Visible=false; return end
    if processed or UIS:GetFocusedTextBox() then return end
    if pressed==settings.key and dockVisible then setOpen(not opened)
    elseif pressed==settings.dockKey then setDockVisible(not dockVisible)
