function runtime.stopFreecam(resume)
    local owned=runtime.freecam; if not owned then return end
    runtime.freecam=nil; Run:UnbindFromRenderStep("ISBFreecam")
    if runtime.freecamControls then runtime.freecamControls:UnbindAction("ISBFreecamMovement") end
    UIS.MouseBehavior=owned.mouseBehavior; UIS.MouseIconEnabled=owned.mouseIcon
    if owned.camera.Parent then
        owned.camera.CameraType=owned.kind
        owned.camera.CameraSubject=owned.subject and owned.subject.Parent and owned.subject or humanoid()
        owned.camera.CFrame=owned.frame; owned.camera.Focus=owned.focus; owned.camera.FieldOfView=owned.fov
    end
    if owned.fly and resume~=false and alive then state.fly=true; startFly() end
end
function runtime.teleportFromFreecam()
    local owned=runtime.freecam; local part=root(); local h=humanoid()
    if not owned then return end
    if not part or not h or h.Health<=0 then notify("Charakter ist gerade nicht verf\195\188gbar.","Freecam"); return end
    if workspace.CurrentCamera~=owned.camera then
        if not runtime.attachFreecamCamera() then notify("Kamera ist gerade nicht verf\195\188gbar.","Freecam"); return end
        owned.camera.CFrame=CFrame.new(owned.position)*CFrame.Angles(0,owned.yaw,0)*CFrame.Angles(owned.pitch,0,0)
    end
    local destination=owned.camera.CFrame.Position
    local look=owned.camera.CFrame.LookVector
    local forward=Vector3.new(look.X,0,look.Z)
    if forward.Magnitude<.0001 then forward=Vector3.new(-math.sin(owned.yaw),0,-math.cos(owned.yaw)) end
    part.CFrame=CFrame.lookAt(destination,destination+forward.Unit,Vector3.new(0,1,0))
    part.AssemblyLinearVelocity=Vector3.zero; part.AssemblyAngularVelocity=Vector3.zero
    local distance=math.max(.5,(owned.frame.Position-owned.focus.Position).Magnitude)
    local focus=destination+owned.focusOffset
    owned.frame=CFrame.lookAt(focus-look*distance,focus,owned.camera.CFrame.UpVector)
    owned.focus=CFrame.new(focus)
    runtime.safeGround=nil; if runtime.voidGround then runtime.voidGround.reset()end
    runtime.stopFreecam(false)
    notify("An Kameraposition teleportiert \194\183 Freecam beendet","Freecam","eye")
end
function runtime.setFreecamSuspended(suspended)
    local owned=runtime.freecam; if not owned then return end
    owned.suspended=suspended; owned.skipMouse=true
    UIS.MouseBehavior=suspended and owned.mouseBehavior or Enum.MouseBehavior.LockCenter
    UIS.MouseIconEnabled=suspended and owned.mouseIcon or false
end
function runtime.attachFreecamCamera()
    local owned=runtime.freecam; local camera=workspace.CurrentCamera
    if not owned or not camera then return false end
    if camera~=owned.camera then
        pcall(function()
            owned.camera.CameraType=owned.kind; owned.camera.CameraSubject=owned.subject and owned.subject.Parent and owned.subject or humanoid()
            owned.camera.CFrame=owned.frame; owned.camera.Focus=owned.focus; owned.camera.FieldOfView=owned.fov
        end)
        owned.cameras=owned.cameras or {}
        owned.cameras[owned.camera]={kind=owned.kind,subject=owned.subject,frame=owned.frame,focus=owned.focus,fov=owned.fov,focusOffset=owned.focusOffset}
        owned.camera=camera
        local saved=owned.cameras[camera]
        if saved then
            owned.kind=saved.kind; owned.subject=saved.subject; owned.frame=saved.frame; owned.focus=saved.focus; owned.fov=saved.fov; owned.focusOffset=saved.focusOffset
        else
            if camera.CameraType~=Enum.CameraType.Scriptable then owned.kind=camera.CameraType end
            owned.subject=camera.CameraSubject; owned.frame=camera.CFrame; owned.focus=camera.Focus; owned.fov=camera.FieldOfView
            owned.focusOffset=camera.Focus.Position-(root() and root().Position or camera.Focus.Position)
        end
    end
    camera.CameraType=Enum.CameraType.Scriptable
    return true
end
function runtime.updateFreecam(dt)
    local owned=runtime.freecam; if not owned then return end
    if not runtime.attachFreecamCamera() then return end
    local paused=owned.suspended or UIS:GetFocusedTextBox()~=nil
    local delta=not paused and not owned.skipMouse and UIS:GetMouseDelta() or Vector2.zero
    owned.skipMouse=false
    owned.pitch=math.clamp(owned.pitch-delta.Y*.003,-math.pi/2+.01,math.pi/2-.01)
    owned.yaw=owned.yaw-delta.X*.003
    local rotation=CFrame.Angles(0,owned.yaw,0)*CFrame.Angles(owned.pitch,0,0)
    local function axis(positive,negative) return (UIS:IsKeyDown(positive) and 1 or 0)-(UIS:IsKeyDown(negative) and 1 or 0) end
    local direction=rotation.LookVector*axis(Enum.KeyCode.W,Enum.KeyCode.S)+rotation.RightVector*axis(Enum.KeyCode.D,Enum.KeyCode.A)
        +Vector3.new(0,axis(Enum.KeyCode.E,Enum.KeyCode.Q),0)
    if direction.Magnitude>1 then direction=direction.Unit end
    local speed=UIS:IsKeyDown(Enum.KeyCode.LeftShift) and 360 or 120
    if not paused then owned.position=owned.position+direction*speed*math.min(dt or 1/60,.1) end
    owned.camera.CFrame=CFrame.new(owned.position)*rotation
    owned.camera.Focus=owned.camera.CFrame*CFrame.new(0,0,-16)
end
function runtime.toggleFreecam()
    if runtime.recovery then runtime.recovery.cancel(true)end
    if runtime.freecam then runtime.stopFreecam(); return end
    local camera=workspace.CurrentCamera; if not camera then return end
    restoreCamera(); runtime.stopRoleplay()
    local pitch,yaw=camera.CFrame:ToOrientation()
    runtime.freecam={camera=camera,kind=camera.CameraType,subject=camera.CameraSubject,frame=camera.CFrame,focus=camera.Focus,fov=camera.FieldOfView,
        mouseBehavior=UIS.MouseBehavior,mouseIcon=UIS.MouseIconEnabled,position=camera.CFrame.Position,pitch=pitch,yaw=yaw,fly=state.fly,
        focusOffset=camera.Focus.Position-(root() and root().Position or camera.Focus.Position)}
    if state.fly then state.fly=false; stopFly() end
    camera.CameraType=Enum.CameraType.Scriptable
    UIS.MouseBehavior=Enum.MouseBehavior.LockCenter; UIS.MouseIconEnabled=false
    runtime.freecamControls=optionalService("ContextActionService")
    if runtime.freecamControls then
        runtime.freecamControls:BindActionAtPriority("ISBFreecamMovement",function() return Enum.ContextActionResult.Sink end,false,3000,
            Enum.KeyCode.W,Enum.KeyCode.A,Enum.KeyCode.S,Enum.KeyCode.D,Enum.KeyCode.E,Enum.KeyCode.Q,Enum.KeyCode.Space,Enum.KeyCode.LeftControl,Enum.KeyCode.LeftShift)
    end
    setOpen(false); setQuickSearch(false)
    Run:BindToRenderStep("ISBFreecam",Enum.RenderPriority.Camera.Value+1,runtime.updateFreecam)
    notify("WASD bewegen \194\183 E/Q hoch/runter \194\183 Shift schneller \194\183 "..settings.freecamKey.." beenden \194\183 "..settings.freecamTeleportKey.." hierhin teleportieren","Freecam","eye")
end

