function runtime.resolveServerRegion(peer)
    if runtime.regionRequest then return end
    local ip=tostring(peer or ""):match("(%d+%.%d+%.%d+%.%d+)")
    if not ip then return end
    local octets={}
    for octet in ip:gmatch("%d+") do table.insert(octets,tonumber(octet)) end
    if #octets~=4 then return end
    for _,octet in ipairs(octets) do if octet>255 then return end end
    local a,b=octets[1],octets[2]
    if a==0 or a==10 or a==127 or a>=224 or (a==169 and b==254) or (a==172 and b>=16 and b<=31) or (a==192 and b==168) or (a==100 and b>=64 and b<=127) then return end
    runtime.regionRequest=true
    task.spawn(function()
        -- Always specify the server peer. An empty GeoIP URL would locate us.
        local ok,data=pcall(requestJSON,"https://ipwho.is/"..ip.."?fields=success,ip,city,region,country,country_code")
        if not alive then return end
        if ok and type(data)=="table" and data.success==true and data.ip==ip then
            local city=tostring(data.city or data.region or "")
            local country=tostring(data.country_code or data.country or "")
            if city~="" or country~="" then runtime.serverRegion="Verbindung: "..city..(city~="" and country~="" and " \194\183 " or "")..country end
        end
        if not runtime.serverRegion then runtime.serverRegion="Verbindungsregion nicht abrufbar" end
    end)
end
function runtime.refreshServerRegion()
    for _,source in ipairs({workspace,game}) do
        for _,name in ipairs({"ServerRegion","ServerLocation","ServerCountry"}) do
            local ok,value=pcall(function() return source:GetAttribute(name) end)
            if ok and type(value)=="string" and value~="" then runtime.serverRegion="Server: "..value:sub(1,70); return end
        end
    end
    local network=optionalService("NetworkClient")
    if network then pcall(function() connect(network.ConnectionAccepted,runtime.resolveServerRegion) end) end
    local logs=optionalService("LogService")
    if logs then
        pcall(function()
            local history=logs:GetLogHistory()
            for i=#history,1,-1 do
                local message=tostring(history[i].message or "")
                local peer=message:match("Connection accepted from%s+([%d%.]+)") or message:match("UDMUX Address%s*=%s*([%d%.]+)") or message:match("serverId:%s*([%d%.]+)")
                if peer then runtime.resolveServerRegion(peer); break end
            end
        end)
    end
    if not runtime.regionRequest then runtime.serverRegion="Server meldet keine Region" end
end
runtime.refreshServerRegion()
