dock.GroupTransparency=1
-- The greeting shares the dock glass, followed by a staggered left-to-right reveal.
function runtime.startWelcomeIntro()
    runtime.welcomeActive=true
    runtime.prepareUISound("intro")
    local welcome=make("CanvasGroup",{Name="WelcomeCapsule",BackgroundColor3=dock.BackgroundColor3,
        AnchorPoint=dock.AnchorPoint,Position=dock.Position+UDim2.fromOffset(0,16),Size=dock.Size,
        GroupTransparency=1,ZIndex=30},host)
    round(welcome,28); runtime.glassSurface(welcome,28); stroke(welcome)
    local greeting=label(welcome,"Hey "..player.DisplayName,18,C.text,UDim2.fromOffset(22,17),UDim2.new(1,-44,0,24),false)
    greeting.TextTransparency=1; greeting.ZIndex=31
    local stages={}; local ordered={runtime.dockClockPanel}
    for _,name in ipairs(navNames) do table.insert(ordered,navButtons[name]) end
    table.insert(ordered,profile)
    indicator.Visible=false
    for i,obj in ipairs(ordered) do
        local position=obj.Position
        -- CanvasGroup clips its render target even when ClipsDescendants is false.
        -- Reserve space for the full hover lift and scale during the reveal.
        local revealPosition=position+UDim2.fromOffset(-8,-8)
        local layer=make("CanvasGroup",{Name="WelcomeReveal_"..i,BackgroundTransparency=1,GroupTransparency=1,
            Position=revealPosition+UDim2.fromOffset(0,8),Size=obj.Size+UDim2.fromOffset(16,16),ClipsDescendants=false,ZIndex=obj.ZIndex or 1},dock)
        table.insert(stages,{obj=obj,layer=layer,position=position,revealPosition=revealPosition,active=obj.Active})
        obj.Parent=layer; obj.Position=UDim2.fromOffset(8,8); obj.Active=false
    end
    function runtime.finishWelcome(cancel)
        if not runtime.welcomeActive then return end
        runtime.welcomeActive=false
        for _,stage in ipairs(stages) do
            if stage.obj.Parent then stage.obj.Parent=dock; stage.obj.Position=stage.position; stage.obj.Active=stage.active end
            if stage.layer.Parent then stage.layer:Destroy() end
        end
        indicator.Visible=true; dock.GroupTransparency=0
        if welcome.Parent then welcome:Destroy() end
        if not cancel and dockVisible then setOpen(settings.autoOpen); notify(CONFIG.Name.." bereit \226\128\162 "..settings.key.." \195\182ffnet das Men\195\188") end
    end
    animate(welcome,{GroupTransparency=0,Position=dock.Position}); animate(greeting,{TextTransparency=0})
    task.delay(settings.reducedMotion and 0 or 2.8,function()
        if not alive or not runtime.welcomeActive then return end
        animate(greeting,{TextTransparency=1}); animate(welcome,{GroupTransparency=1})
        if dockVisible then animate(dock,{GroupTransparency=0}) end
    end)
    for i,stage in ipairs(stages) do
        task.delay(settings.reducedMotion and 0 or (3.02+(i-1)*.15),function()
            if alive and runtime.welcomeActive and dockVisible then
                animate(stage.layer,{GroupTransparency=0,Position=stage.revealPosition})
                if i>1 and not settings.reducedMotion then playUISound("intro",.94+(i-2)*.025) end
            end
        end)
    end
    task.delay(settings.reducedMotion and 0 or (3.02+(#stages-1)*.15+.32),function()
        if alive then runtime.finishWelcome(false) end
    end)
end
runtime.startWelcomeIntro()
return api
